// Validasi: sumber harus nama produk atau judul dokumen yang benar-benar ada; tanpa sumber valid -> ganti jawaban aman.
const out = $('Asisten Penjualan').first().json.output || {};
const base = $('Siapkan Input').first().json;
const names = ($json.nama || []).map(s => String(s).toLowerCase());
const docs = ["Dokumen: FAQ Pembayaran dan Jam Operasional", "Dokumen: Kebijakan Pengiriman", "Dokumen: Kebijakan Retur dan Refund", "Dokumen: Garansi Tas dan Pouch", "Dokumen: Pembelian Grosir dan Kerja Sama"].map(s => s.toLowerCase());
const known = [...names, ...docs];
const sumber = (out.sumber || []).filter(s => {
  const x = String(s).toLowerCase().trim();
  return known.some(k => k === x || (x.length >= 8 && (k.includes(x) || x.includes(k))));
});
let jawaban = String(out.jawaban || '');
let ditolak = Boolean(out.ditolak);
let validasi = 'ok';
if (out.eskalasi && sumber.length === 0) {
  validasi = 'eskalasi_tanpa_sumber';
} else if (!ditolak && sumber.length === 0) {
  jawaban = 'Maaf, aku belum bisa memastikan jawabannya dari katalog atau dokumen toko. Pertanyaanmu aku teruskan ke admin ya.';
  ditolak = true;
  validasi = 'tanpa_sumber_valid';
}
return [{ json: { session_id: base.session_id, jawaban, sumber, ditolak, eskalasi: Boolean(out.eskalasi), validasi, ada_foto: base.has_image } }];
